interface.web/styles.css:
:root { --accent: #1748a3; --ink: #152036; --paper: #ffffff; --space: 1rem; }
body { color: var(--ink); background: var(--paper); font: 1rem/1.5 system-ui; margin: var(--space); }
main { max-width: 60rem; margin: auto; }
textarea { display: block; width: 100%; min-height: 10rem; box-sizing: border-box; }
button { background: var(--accent); color: white; padding: .75rem 1rem; }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 3px; }
@media (min-width: 40rem) { main { padding: 2rem; } }

interface.web/app.js:
const form = document.getElementById("labels");
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const labels = document.getElementById("source").value.split("\n");
  document.getElementById("result").textContent = labels.map((label) => label.trim()).join("\n");
});

